-- ============================================================
-- SEED: signs, templates, sizes, usages from signage_data_v5.xlsx
-- Run AFTER schema_v7.sql.
--
-- Strategy:
--   - Use xlsx string IDs (T05, TPL01, SZ001, SG0001) as lookup keys
--   - Match to UUID-keyed rows by name where possible
--   - Usages are attributed to the seeded venue 'Saifee Nagar Chennai'
--     and zone 'CMZ' since the xlsx predates the venue/zone model
-- ============================================================

begin;

-- The schema declares signs.department_id as NOT NULL (hard ownership). The
-- 187 sign rows below predate that constraint and have no dept yet. We:
--   1. drop NOT NULL temporarily,
--   2. seed signs + usages,
--   3. backfill department_id per sign from its dominant usage dept,
--   4. fall back to 'General' for orphan signs (no usage history),
--   5. re-enable NOT NULL.
alter table signs alter column department_id drop not null;
  on conflict (name) do nothing;

-- ---------- sizes ----------


-- ---------- sign_templates ----------

-- ---------- signs ----------

-- ---------- usages ----------
-- Map xlsx usage rows to current schema.
-- - sign_id: lookup by canonical_name
-- - department_id: lookup by name (match through xlsx departments sheet)
-- - event_id: parse 'event' string e.g. '1447 / Chennai'
-- - venue_id: 'Saifee Nagar Chennai' (placeholder)
-- - zone_id: 'CMZ'
-- - size_id: lookup by xlsx label


-- ---------- backfill signs.department_id ----------
-- Dominant dept per sign (most-frequent usage; ties → earliest first_seen).
update signs s set department_id = sub.dept_id
  from (
    select sign_id,
           (array_agg(department_id order by cnt desc, first_seen asc))[1] as dept_id
      from (
        select sign_id, department_id,
               count(*)         as cnt,
               min(created_at)  as first_seen
          from usages
         group by sign_id, department_id
      ) g
     group by sign_id
  ) sub
 where s.id = sub.sign_id
   and s.department_id is null;

-- Orphans (no usage history) → General
update signs
   set department_id = (select id from departments where name = 'General')
 where department_id is null;

-- Re-enable the constraint now that every sign owns a department.
alter table signs alter column department_id set not null;

commit;

-- Sanity checks
-- select count(*) from sign_templates;       -- expect 6
-- select count(*) from sizes;                -- expect 6
-- select count(*) from signs;                -- expect 187
-- select count(*) from usages;               -- expect 199
-- select count(*) from signs where department_id is null;  -- expect 0